import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, double margin);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>

#define TRIPLET_EPS 1e-6f
#define BLOCK_THREADS 512
#define WARPS_PER_BLOCK (BLOCK_THREADS / 32)

__global__ void triplet_margin_loss_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ row_loss,
    const int B,
    const int N,
    const float margin
) {
    const int row = blockIdx.x;
    if (row >= B) return;

    const size_t base = (size_t)row * (size_t)N;
    const float* a = anchor + base;
    const float* p = positive + base;
    const float* n = negative + base;

    float acc_pos = 0.0f;
    float acc_neg = 0.0f;

    const int nvec = N >> 2;
    const float4* a4 = reinterpret_cast<const float4*>(a);
    const float4* p4 = reinterpret_cast<const float4*>(p);
    const float4* n4 = reinterpret_cast<const float4*>(n);

    const int stride4 = BLOCK_THREADS * 4;
    int i = threadIdx.x;
    for (; i + 3 * BLOCK_THREADS < nvec; i += stride4) {
        const float4 av0 = a4[i];
        const float4 pv0 = p4[i];
        const float4 nv0 = n4[i];
        const float4 av1 = a4[i + BLOCK_THREADS];
        const float4 pv1 = p4[i + BLOCK_THREADS];
        const float4 nv1 = n4[i + BLOCK_THREADS];
        const float4 av2 = a4[i + 2 * BLOCK_THREADS];
        const float4 pv2 = p4[i + 2 * BLOCK_THREADS];
        const float4 nv2 = n4[i + 2 * BLOCK_THREADS];
        const float4 av3 = a4[i + 3 * BLOCK_THREADS];
        const float4 pv3 = p4[i + 3 * BLOCK_THREADS];
        const float4 nv3 = n4[i + 3 * BLOCK_THREADS];
        const float dp00 = av0.x - pv0.x + TRIPLET_EPS;
        const float dp01 = av0.y - pv0.y + TRIPLET_EPS;
        const float dp02 = av0.z - pv0.z + TRIPLET_EPS;
        const float dp03 = av0.w - pv0.w + TRIPLET_EPS;
        const float dn00 = av0.x - nv0.x + TRIPLET_EPS;
        const float dn01 = av0.y - nv0.y + TRIPLET_EPS;
        const float dn02 = av0.z - nv0.z + TRIPLET_EPS;
        const float dn03 = av0.w - nv0.w + TRIPLET_EPS;
        const float dp10 = av1.x - pv1.x + TRIPLET_EPS;
        const float dp11 = av1.y - pv1.y + TRIPLET_EPS;
        const float dp12 = av1.z - pv1.z + TRIPLET_EPS;
        const float dp13 = av1.w - pv1.w + TRIPLET_EPS;
        const float dn10 = av1.x - nv1.x + TRIPLET_EPS;
        const float dn11 = av1.y - nv1.y + TRIPLET_EPS;
        const float dn12 = av1.z - nv1.z + TRIPLET_EPS;
        const float dn13 = av1.w - nv1.w + TRIPLET_EPS;
        const float dp20 = av2.x - pv2.x + TRIPLET_EPS;
        const float dp21 = av2.y - pv2.y + TRIPLET_EPS;
        const float dp22 = av2.z - pv2.z + TRIPLET_EPS;
        const float dp23 = av2.w - pv2.w + TRIPLET_EPS;
        const float dn20 = av2.x - nv2.x + TRIPLET_EPS;
        const float dn21 = av2.y - nv2.y + TRIPLET_EPS;
        const float dn22 = av2.z - nv2.z + TRIPLET_EPS;
        const float dn23 = av2.w - nv2.w + TRIPLET_EPS;
        const float dp30 = av3.x - pv3.x + TRIPLET_EPS;
        const float dp31 = av3.y - pv3.y + TRIPLET_EPS;
        const float dp32 = av3.z - pv3.z + TRIPLET_EPS;
        const float dp33 = av3.w - pv3.w + TRIPLET_EPS;
        const float dn30 = av3.x - nv3.x + TRIPLET_EPS;
        const float dn31 = av3.y - nv3.y + TRIPLET_EPS;
        const float dn32 = av3.z - nv3.z + TRIPLET_EPS;
        const float dn33 = av3.w - nv3.w + TRIPLET_EPS;
        acc_pos += dp00 * dp00 + dp01 * dp01 + dp02 * dp02 + dp03 * dp03;
        acc_neg += dn00 * dn00 + dn01 * dn01 + dn02 * dn02 + dn03 * dn03;
        acc_pos += dp10 * dp10 + dp11 * dp11 + dp12 * dp12 + dp13 * dp13;
        acc_neg += dn10 * dn10 + dn11 * dn11 + dn12 * dn12 + dn13 * dn13;
        acc_pos += dp20 * dp20 + dp21 * dp21 + dp22 * dp22 + dp23 * dp23;
        acc_neg += dn20 * dn20 + dn21 * dn21 + dn22 * dn22 + dn23 * dn23;
        acc_pos += dp30 * dp30 + dp31 * dp31 + dp32 * dp32 + dp33 * dp33;
        acc_neg += dn30 * dn30 + dn31 * dn31 + dn32 * dn32 + dn33 * dn33;
    }
    for (; i < nvec; i += BLOCK_THREADS) {
        const float4 av = a4[i];
        const float4 pv = p4[i];
        const float4 nv = n4[i];
        const float dp0 = av.x - pv.x + TRIPLET_EPS;
        const float dp1 = av.y - pv.y + TRIPLET_EPS;
        const float dp2 = av.z - pv.z + TRIPLET_EPS;
        const float dp3 = av.w - pv.w + TRIPLET_EPS;
        const float dn0 = av.x - nv.x + TRIPLET_EPS;
        const float dn1 = av.y - nv.y + TRIPLET_EPS;
        const float dn2 = av.z - nv.z + TRIPLET_EPS;
        const float dn3 = av.w - nv.w + TRIPLET_EPS;
        acc_pos += dp0 * dp0 + dp1 * dp1 + dp2 * dp2 + dp3 * dp3;
        acc_neg += dn0 * dn0 + dn1 * dn1 + dn2 * dn2 + dn3 * dn3;
    }

    for (int j = (nvec << 2) + threadIdx.x; j < N; j += BLOCK_THREADS) {
        const float dp = a[j] - p[j] + TRIPLET_EPS;
        const float dn = a[j] - n[j] + TRIPLET_EPS;
        acc_pos += dp * dp;
        acc_neg += dn * dn;
    }

    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        acc_pos += __shfl_down_sync(0xffffffffu, acc_pos, off);
        acc_neg += __shfl_down_sync(0xffffffffu, acc_neg, off);
    }

    __shared__ float shared_pos[WARPS_PER_BLOCK];
    __shared__ float shared_neg[WARPS_PER_BLOCK];

    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;

    if (lane == 0) {
        shared_pos[warp] = acc_pos;
        shared_neg[warp] = acc_neg;
    }
    __syncthreads();

    if (warp == 0) {
        acc_pos = (lane < WARPS_PER_BLOCK) ? shared_pos[lane] : 0.0f;
        acc_neg = (lane < WARPS_PER_BLOCK) ? shared_neg[lane] : 0.0f;

        #pragma unroll
        for (int off = WARPS_PER_BLOCK / 2; off > 0; off >>= 1) {
            acc_pos += __shfl_down_sync(0xffffffffu, acc_pos, off);
            acc_neg += __shfl_down_sync(0xffffffffu, acc_neg, off);
        }

        if (lane == 0) {
            const float d_pos = sqrtf(acc_pos);
            const float d_neg = sqrtf(acc_neg);
            const float loss = fmaxf(d_pos - d_neg + margin, 0.0f);
            row_loss[row] = loss;
        }
    }
}

__global__ void reduce_row_loss_kernel(
    const float* __restrict__ row_loss,
    float* __restrict__ out,
    const int B,
    const float invB
) {
    float acc = 0.0f;
    for (int i = threadIdx.x; i < B; i += BLOCK_THREADS) {
        acc += row_loss[i];
    }
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        acc += __shfl_down_sync(0xffffffffu, acc, off);
    }
    __shared__ float shared[WARPS_PER_BLOCK];
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    if (lane == 0) shared[warp] = acc;
    __syncthreads();
    if (warp == 0) {
        acc = (lane < WARPS_PER_BLOCK) ? shared[lane] : 0.0f;
        #pragma unroll
        for (int off = WARPS_PER_BLOCK / 2; off > 0; off >>= 1) {
            acc += __shfl_down_sync(0xffffffffu, acc, off);
        }
        if (lane == 0) out[0] = acc * invB;
    }
}
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, double margin) {
    TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(anchor.scalar_type() == at::kFloat && positive.scalar_type() == at::kFloat && negative.scalar_type() == at::kFloat, "inputs must be float32");
    TORCH_CHECK(anchor.dim() == 2 && positive.dim() == 2 && negative.dim() == 2, "inputs must be 2D [batch, features]");
    TORCH_CHECK(anchor.is_contiguous() && positive.is_contiguous() && negative.is_contiguous(), "inputs must be contiguous");

    const int64_t B64 = anchor.size(0);
    const int64_t N64 = anchor.size(1);
    TORCH_CHECK(positive.size(0) == B64 && positive.size(1) == N64, "positive shape mismatch");
    TORCH_CHECK(negative.size(0) == B64 && negative.size(1) == N64, "negative shape mismatch");
    TORCH_CHECK(B64 <= 0x7fffffffLL && N64 <= 0x7fffffffLL, "shape too large");

    c10::cuda::CUDAGuard guard(anchor.device());
    auto out = at::empty({}, anchor.options());
    auto row_loss = at::empty({B64}, anchor.options());
    const int B = (int)B64;
    const int N = (int)N64;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    if (B == 0) {
        cudaMemsetAsync(out.data_ptr<float>(), 0, sizeof(float), stream);
        return out;
    }
    dim3 grid((unsigned)B);
    dim3 block(BLOCK_THREADS);
    triplet_margin_loss_kernel<<<grid, block, 0, stream>>>(
        anchor.data_ptr<float>(),
        positive.data_ptr<float>(),
        negative.data_ptr<float>(),
        row_loss.data_ptr<float>(),
        B,
        N,
        (float)margin
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    reduce_row_loss_kernel<<<1, block, 0, stream>>>(
        row_loss.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        1.0f / (float)B
    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
"""

_triplet_cuda = load_inline(
    name="triplet_margin_loss_single_kernel",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["triplet_margin_loss_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)

    def forward(self, anchor, positive, negative):
        return _triplet_cuda.triplet_margin_loss_forward(anchor, positive, negative, self.margin)

